let b2SupplementId = 7001;
const B2_COURSE_SUPPLEMENTS = Object.entries(B2_COURSE_SUPPLEMENT_TERMS).flatMap(([lesson, terms]) => terms.split(';').map(entry => {
  const [word, zh] = entry.split('|');
  return { id: `w${b2SupplementId++}`, word, pos: 'phrase', ipa: `/${word}/`, zh, example: `El informe incorpora ${word} para aclarar el caso.`, example_zh: `报告纳入“${zh}”以澄清该案例。`, lesson, stress: 2, extra: true };
}));

function b2BuildWords(lessons, start) {
  let n = start;
  return lessons.flatMap(lesson => lesson.terms.split(';').map((entry, index) => {
    const [word, zh] = entry.split('|');
    return { id:`w${n++}`, word, pos:'phrase', ipa:`/${word}/`, zh, example:`En el contexto de ${lesson.context}, se emplea «${word}».`, example_zh:`在“${lesson.context}”的语境中使用“${zh}”。`, lesson:lesson.id, stress:2, extra:index >= 13 };
  }));
}
const WORDS_P7A = b2BuildWords(B2_1_LESSONS, 4001);
const DIALOGS_P7A = Object.fromEntries(B2_1_LESSONS.map(x => [x.id, x.dialog.map(([es, zh], i) => ({speaker:i % 2 ? 'B':'A',es,zh}))]));
// Each source question keeps its pedagogical answer. Rotating the presented
// options gives the data layer a balanced answer-index distribution too.
function b2BuildListening(lessons, offset) {
  return lessons.map((x, lessonIndex) => ({
    id: x.id,
    text: x.listening.text,
    questions: x.listening.questions.map(([q, options, answer, tip], questionIndex) => {
      const shift = (offset + lessonIndex * 2 + questionIndex) % options.length;
      return {
        q,
        options: options.map((_, index) => options[(index + shift) % options.length]),
        answer: (answer - shift + options.length) % options.length,
        tip
      };
    })
  }));
}

const LISTENING_P7A = b2BuildListening(B2_1_LESSONS, 0);
const WORDS_P7B = b2BuildWords(B2_2_LESSONS, 5001);
const DIALOGS_P7B = Object.fromEntries(B2_2_LESSONS.map(x => [x.id, x.dialog.map(([es, zh], i) => ({speaker:i % 2 ? 'B':'A',es,zh}))]));
const LISTENING_P7B = b2BuildListening(B2_2_LESSONS, 1);

// These are deliberately a review pool rather than inflated lesson lists.
// They supply recurring formal-discourse vocabulary without violating the
// 13 core + 26 extension words per B2 lesson contract.
const B2_REVIEW_TERMS = `abordar|处理;alcance|范围;ambigüedad|歧义;ámbito|领域;aportar|提供;asumir|承担;coherente|连贯的;contemplar|考虑;criterio|标准;cuestionar|质疑;desempeñar|履行;destacar|突出;difundir|传播;disponer de|拥有;eficaz|有效的;enfoque|视角;entorno|环境;equidad|公平;escasez|短缺;establecer|建立;evaluar|评估;evitar|避免;favorecer|促进;gestionar|管理;implicar|涉及;incidir en|影响;indicar|表明;iniciativa|倡议;lograr|实现;marco|框架;mejorar|改善;objetivo|目标;obstáculo|障碍;pertinente|恰当的;planteamiento|论述方式;prever|预见;priorizar|优先处理;profundizar|深入探讨;proponer|提出;reconocer|承认;recurso|资源;reducir|减少;reflejar|反映;relevante|重要的;resaltar|强调;resolver|解决;respaldar|支持;resultar|产生结果;revisión|审查;riesgo|风险;señalar|指出;sostenible|可持续的;subrayar|着重指出;suponer|意味着;tendencia|趋势;trasladar|转达;valorar|评估价值;viable|可行的;vínculo|联系;vulnerable|脆弱的;adverso|不利的;consistente|一致的;debatir|辩论;delimitar|界定`;
const B2_REVIEW_EXTRA_TERMS = `acotar|限定范围;adoptar un enfoque|采取视角;albergar dudas|心存疑问;analizar en profundidad|深入分析;anteponer|置于优先;argumentar con rigor|严谨论证;asociar|关联;atender a|注意到;atribuir responsabilidad|归责;calibrar|衡量;clarificar|澄清;converger|趋同;corroborar|佐证;desglosar|分项说明;desplazar el debate|转移辩题;detectar un sesgo|发现偏见;dimensionar|评估规模;discrepar razonadamente|理性不同意;efectuar un seguimiento|进行跟进;encajar en el marco|纳入框架;enriquecer el análisis|丰富分析;esbozar una propuesta|概述提案;establecer prioridades|确立优先项;fundamentar una decisión|为决定提供依据;garantizar la trazabilidad|保证可追溯性;identificar una carencia|识别缺口;integrar perspectivas|整合视角;justificar el criterio|说明标准;moderar el alcance|控制范围;ponderar alternativas|权衡替代方案`;
const B2_REVIEW_WORDS = (B2_REVIEW_TERMS + ';' + B2_REVIEW_EXTRA_TERMS).split(';').map((entry, index) => {
  const [word, zh] = entry.split('|');
  return {
    id: `w${6001 + index}`,
    word,
    pos: 'phrase',
    ipa: `/${word}/`,
    zh,
    example: `Conviene ${word} el asunto antes de tomar una decisión.`,
    example_zh: `在作出决定前，应当先${zh}这个问题。`,
    lesson: 'B2-REV',
    stress: 2,
    extra: true
  };
});
